-- 0160:
-- Opposites (30-KIN, ar_ling_root_didd) for the 13 roots of Ghāfir 40:1–3 — second pass after 0141.
-- A. The four roots with no opposite (توب, عقب, صير, اله) re-checked in all ten lexicons (through
--    ar_ling_root_lexicon_block_v, both roots of each pair) and in the eight tafsīrs (text_norm LIKE).
--    توب ↔ إِصْرَار: no lexicon says ضدّ/نقيض, but the books define each by the other — al-Rāghib: tawba =
--      desisting (أقلع), iṣrār = refusing to desist (الامتناع من الإقلاع); Lisān/Tāj: «أصرّ على الذنب: لم يقلع عنه»;
--      al-Ṭabarī on 3:135: «الإصرار: الإقامة على الذنب عامدا، وترك التوبة منه»; Ibn ʿĀshūr on 3:135: its
--      negation «هو التوبة». → antonym. No verse holds both words (3:135 has استغفروا + لم يصروا), so no display.
--      تَمَادٍ / إقامة على الذنب: folded in — it is al-Ṭabarī's definition of iṣrār, not a separate word pair.
--    عقب: عِقَاب ↔ مَغْفِرَة — the Qurʾān sets them side by side (40:3, 41:43, 13:6); Ibn ʿĀshūr on 13:6 calls
--      the punishment «ضد تلك المغفرة». No lexicon pairs them → antithetical_pair.
--      عِقَاب ↔ ثَوَاب — the two sides of recompense (al-Ṭabarī on 5:98; Ibn ʿĀshūr on 40:3; al-Rāghib p.575
--      splits the root: عُقْبى for reward, عِقاب for punishment). Nobody says ضدّ → contrast. No verse holds both
--      (3:148 and 3:195 have ثواب only). عَقِب (heel/after) ↔ ?: no book states one.
--    صير, اله: nothing in any book. Rejected: al-Rāzī on 2:126 «بئس المصير ضدّه» (opposes two kinds of end, not
--      مصير itself); Lane's "contr." under اله is about pronouncing the lām (tarqīq), not meaning.
-- B. Audit of the 22 live rows: all had antonym_en, note_en and both global root ids. Fixed:
--    source_ref without block ids/pages (AN:شدد:1, AN:شدد:2, AN:طول:1, the three قبل rows, كتب:محو, كتب:اغفل);
--    relation_kind 'contrary' (not a kind) → 'contrast' (كتب:اغفل); academic note_en rewritten plainly;
--    rows whose opposite belongs to ANOTHER word of the root than the passage lemma now say so first in note_en
--    (ذَنَب tail, طُول length, شَدّ tying, مَعْلَم waymark, عَزَّ weak, غَفِرَ of a wound, أَقْبَلَ/قَبْل/قُبُل,
--    كَتَبَ gather, نُزُول). Nothing deleted.
--    Gap filled for قَابِل (accepting): قَبِلَ ↔ رَدَّ, stated under ردد («ردّ عليه الشيء إذا لم يقبله»).
-- Still no opposite: صير, اله; ذَنْب (sin); طَوْل (bounty); تَنزِيل (sending down).

-- ── A. new rows ─────────────────────────────────────────────────────────────────────────────────────────
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json, root_id, antonym_root_id) VALUES ('DID:توب:صرر', 'توب', 'الإِصْرَار', 'صرر', 'persisting in sin', 'antonym', 1, 'al-Rāghib blk_mfr_dab5f6b697acc4f5, blk_mfr_2599843e71a09969 p.169 (التوبة = «أقلعت»), blk_mfr_9d15f99ee0318329 p.481 («الإصرار: التعقّد في الذنب … والامتناع من الإقلاع عنه»); Lisān blk_lsn_396b3ea2dab53ee4 p.2410 («أصرّ على الذنب لم يُقلِع عنه»), blk_lsn_3a163b05f2fd406a p.2410; Tāj blk_taj_96ebea53fff52a01 p.313; Miṣbāḥ blk_msb_90c7611183a619be p.394 («تاب من ذنبه … أقلع»); Maqāyīs blk_mqy_5066e9100d69f34c p.34; Lane blk_lane_6158992ab499a747 p.1670; al-Ṭabarī on 3:135 QR:TE:TAFSIR_BLK_BF_a4d2b060f772199bac6242c2 («الإصرار، الإقامة على الذنب عامدا، وترك التوبة منه»); Ibn ʿĀshūr on 3:135 QR:TE:TAFSIR_BLK_BF_7d4a754f3dc6cf598a938008 p.92; al-Ālūsī on 3:135 QR:TE:TAFSIR_BLK_BF_42ae44106ea15ca198896494 p.60; al-Zamakhsharī on 3:133 QR:TE:TAFSIR_BLK_BF_d0a3be33f9af52bf1b726629', 'live', 0.8, 'source_stated', 'Turning back from sin ↔ sticking to it. al-Ṭabarī: persisting means staying on a sin and not repenting.', NULL, 'bdf8d03c381a14509c63b50ca4', '805371825cfb46e547efb53cbf');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json, root_id, antonym_root_id) VALUES ('DID:عقب:غفر', 'عقب', 'المَغْفِرَة', 'غفر', 'forgiveness', 'antithetical_pair', 1, 'Qurʾān 40:3, 41:43, 13:6; Ibn ʿĀshūr on 13:6 QR:TE:TAFSIR_BLK_BF_ea71e94ef7291586df783bca p.92 («المراد بالعقاب … ضد تلك المغفرة»); Ibn ʿĀshūr on 40:3 QR:TE:TAFSIR_BLK_ccc63b62e1f5aec8 p.80 (غافر/قابل «ترغيب»، شديد العقاب «ترهيب»); al-Ālūsī on 40:3 QR:TE:TAFSIR_BLK_3df03450355fbb36 p.42', 'live', 0.85, 'source_stated', 'Punishment ↔ forgiveness. No lexicon pairs them; the Qurʾān does, and Ibn ʿĀshūr calls the punishment «ضد تلك المغفرة».', '{"quran":[{"surah":40,"ayah":3,"needle":"غافر الذنب"},{"surah":40,"ayah":3,"needle":"شديد العقاب"},{"surah":41,"ayah":43,"needle":"لذو مغفرة وذو عقاب اليم"}]}', '2cb4f93058ff7723ce0d8cd500', '765f5439c429ab304615af0af0');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json, root_id, antonym_root_id) VALUES ('DID:عقب:ثوب', 'عقب', 'الثَّوَاب', 'ثوب', 'reward', 'contrast', 2, 'al-Rāghib blk_mfr_af04d9696aee7442, blk_mfr_5f66ea2cb595c84d, blk_mfr_69b1dbaafcb19312, blk_mfr_be172382da8f5c43 p.575 («العُقْب والعُقْبى يختصّان بالثواب … والعِقاب يختصّ بالعذاب»); al-Ṭabarī on 5:98 QR:TE:TAFSIR_BLK_BF_65bd360778321990abbc96a0 («إلينا الثواب على الطاعة، وعلينا العقاب على المعصية»); Ibn ʿĀshūr on 40:3 QR:TE:TAFSIR_BLK_ccc63b62e1f5aec8 p.80 («المصير إما إلى ثوابه وإما إلى عقابه»); Ṣiḥāḥ blk_sih_f7e4039e6258bd73 p.172 («الثواب: جزاء الطاعة»)', 'live', 0.7, 'source_stated', 'Punishment ↔ reward: the two sides of being repaid. Paired, never called ضدّ.', NULL, '2cb4f93058ff7723ce0d8cd500', '1f0d60cec6708b053e282f33d9');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json, root_id, antonym_root_id) VALUES ('DID:قبل:ردد', 'قبل', 'الرَّدّ', 'ردد', 'rejecting, refusing', 'antonym', 4, 'Ṣiḥāḥ blk_sih_642fd2160ce1d912 p.930 («ورَدَّ عليه الشيء إذا لم يقبله»); Lisān blk_lsn_a176b25885596f06 p.1614 (same); Tāj blk_taj_457b7cf9a78680a4 p.89; Lane blk_lane_28c223c6ccf36d82 p.1062 («He rejected the thing, refusing to receive it, or accept it»)', 'live', 0.8, 'source_stated', 'Accepting ↔ rejecting. Stated under ردد: to reject is «لم يقبله», not to accept.', NULL, 'af777a646fae4d26b0500117d9', 'f6d461232f61ea70427395a13f');

-- ── B. audit of live rows ──────────────────────────────────────────────────────────────────────────────
UPDATE ar_ling_root_didd SET source_ref = 'Lisān blk_lsn_da2c90cf44770bfd p.1674 («الشدّة: الصلابة، وهي نقيض اللين»)', generated_by = 'source_stated', confidence = 0.85, note_en = 'Hardness ↔ softness. Lisān calls them نقيض, in things and in qualities.' WHERE id = 'AN:شدد:1' AND status = 'live';
UPDATE ar_ling_root_didd SET source_ref = 'Ṣiḥāḥ blk_sih_54b2d2607258b9fb p.969 («والتشديد: خلاف التخفيف»); Lisān blk_lsn_73dd3f1132a4a38a p.1674 (same); Miṣbāḥ blk_msb_d4721fc9569e3fd4 p.1567 («وشدّد عليه ضدّ خفّف»); Lane blk_lane_10e0dabdce36ac12 p.1518 («تَشْدِيدٌ is the contr. of تَخْفِيفٌ»)', generated_by = 'source_stated', confidence = 0.9, note_en = 'Making things hard on someone ↔ making them light. al-Fayyūmī uses the word ضدّ.' WHERE id = 'AN:شدد:2' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For شَدّ, tying fast — not شَدِيد, severe. Tying ↔ untying; stated under حلل (Lane: «contr. of شَدٌّ»).' WHERE id = 'DID:شدد:حلل' AND status = 'live';
UPDATE ar_ling_root_didd SET source_ref = 'Lisān blk_lsn_5297c0c61d222077 p.4922 («الطول: نقيض القصر»), blk_lsn_ddb4f4b80cac2820 p.4922; Tāj blk_taj_9772174e9fd9a304 p.390 (Ibn Jinnī: «الطول ضد القصر»), blk_taj_3038bea487fcb9fa p.390; al-Rāghib blk_mfr_c94adcdbd7d1a907 p.533 («الطول والقصر من الأسماء المتضايفة»); Miṣbāḥ blk_msb_d58340ddb202c815 p.1917 («نقيضه وهو قصر»); Lane blk_lane_1f99f468db43f617 p.1894, blk_lane_9893aadec3455a6a p.1896', generated_by = 'source_stated', confidence = 0.95, note_en = 'For طُول, length — not طَوْل, bounty (40:3). Long ↔ short; Lisān: نقيض.' WHERE id = 'AN:طول:1' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For طُول, length — not طَوْل, bounty (40:3). Length ↔ width: two directions; the books say خلاف, not نقيض.' WHERE id = 'AN:طول:2' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For ذَنَب, tail — not ذَنْب, sin. Followers (the tail) ↔ leaders (the heads). No book gives an opposite for ذَنْب, sin.' WHERE id = 'DID:ذنب:راس' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For مَعْلَم, a marked place — not عَلِيم, knowing. Land with waymarks ↔ trackless land.' WHERE id = 'DID:علم:جهل:2' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For the verb عَزَّ in a rare use — not عَزِيز, mighty. One word, two opposite meanings: was strong, and was weak.' WHERE id = 'DID:عزز:عزز' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For غَفِرَ said of a wound — not غَافِر, forgiving. One word, two opposite meanings: healed, and broke open again. Ibn Fāris calls it rare (شاذّ).' WHERE id = 'DID:غفر:غفر' AND status = 'live';
UPDATE ar_ling_root_didd SET source_ref = 'Ṣiḥāḥ blk_sih_927eab40987553fb (lf_b7be198d791ede62), blk_sih_f2f00962a84a9cc1 (lf_88c6354aab3b29bd) p.3555; Lisān blk_lsn_2855e2f2dfc64001 (lf_b4958fc3b76aad04), blk_lsn_f7369baf5465d1ea (lf_c7ba2f23cfbda300), blk_lsn_313a7096156d6291 (lf_63e60a7968f0d71c), blk_lsn_85bdfdb47e29e73c (lf_66550f516069d6f9) p.1132; Qāmūs blk_qms_705d40102a0f071f (lf_4e700546d093884b), blk_qms_34e90eaa8e405a61 (lf_094229e6f85a6ee3), no printed page; Tāj blk_taj_f24e3f3952f6c8bb p.218 (lf_2bbc55f46730dbcb); Miṣbāḥ blk_msb_15b1af3452c9aa85 p.2421 («فهو قابل خلاف دبر»); Lane blk_lane_7957edae2c49a61c, blk_lane_83996c6025f7ee11, blk_lane_63ad5169b592811a p.2983 (lf_6963c5a6f438df04, lf_b8deb361e4b50896, lf_5c5583e1c59f360e)', note_en = 'For أَقْبَلَ, to come forward — not قَابِل, accepting. Coming forward ↔ turning back; also اِسْتَقْبَلَ ↔ اِسْتَدْبَرَ.' WHERE id = 'DID:قبل:دبر' AND status = 'live';
UPDATE ar_ling_root_didd SET source_ref = 'Ṣiḥāḥ blk_sih_bfaf418e40be4542 p.3555 (lf_e300b47a4118d777); Lisān blk_lsn_6456368ea4d26eb4 p.1132 (lf_367a37d930c8e186); Tāj blk_taj_fc3a8e582c2735a7 p.206 (lf_9baf770639e6330b), blk_taj_5c3158ce8c5948a5 p.440; Qāmūs blk_qms_705d40102a0f071f (lf_ca425a0c8aaf440c), no printed page; Lane blk_lane_ffaad18da1ba4d9e p.2983 (lf_ee543c820950d4b3); Miṣbāḥ blk_msb_8c771491d242b0d1 p.2421 («وقبلُ خلاف بعدُ»); Maqāyīs blk_mqy_eb2a54bd02310019 p.11', note_en = 'For قَبْلُ, before — not قَابِل, accepting. Before ↔ after. Abū Ḥātim (in Tāj) even lists قبل/بعد as one word with two opposite meanings.' WHERE id = 'DID:قبل:بعد' AND status = 'live';
UPDATE ar_ling_root_didd SET source_ref = 'Ṣiḥāḥ blk_sih_bfaf418e40be4542 p.3555 (lf_c2a6dc613dce3781); Lisān blk_lsn_2e9de75f95aab452 p.1132 (lf_51fed38415e2852f, lf_fdb1dac289dc8bef); Tāj blk_taj_8f552738559c8044 p.206 (lf_8c8e1a7489bbf242), blk_taj_53cfb32173e98eca p.223 (lf_e03a926cd527e22a); Qāmūs blk_qms_705d40102a0f071f (lf_85c36d9c305550d5), no printed page; al-ʿAyn blk_kay_0046863c6cd9a58b p.1738; Maqāyīs blk_mqy_de62875efd1ff29c p.11; Miṣbāḥ blk_msb_15b1af3452c9aa85 p.2421; Lane blk_lane_9ce9c17d6158e32f p.2984, blk_lane_e2b8ca35f5633bc5 p.2984 (lf_c96e22196a3d7087, المُقَابَل ↔ المُدَابَر)', note_en = 'For قُبُل, the front — not قَابِل, accepting. Front ↔ back. The Qurʾān has both across 12:26–27.' WHERE id = 'DID:قبل:دبر:2' AND status = 'live';
UPDATE ar_ling_root_didd SET source_ref = 'al-Rāghib blk_mfr_1fa7e4a6cb358c02 p.699 («ويعبّر عن الإيجاد بالكتابة، وعن الإزالة والإفناء بالمحو»); Qāmūs blk_qms_08f3a1e55e8ded89 (lf_197dec6d2ad17185, art. لمق: «الكتابة، والمحو، ضدّ»), no printed page; Qurʾān 13:39' WHERE id = 'DID:كتب:محو' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For كَتَبَ, to gather (as in كَتِيبَة, a troop) — not كِتَاب, book. Gathered ↔ scattered: a definition by what it is not.' WHERE id = 'DID:كتب:نشر' AND status = 'live';
UPDATE ar_ling_root_didd SET relation_kind = 'contrast', confidence = 0.8, source_ref = 'al-Rāghib blk_mfr_1fc34abd03346b30, blk_mfr_aa94ca778b470433, blk_mfr_165e9b1503036d02 p.699 («بخلاف من وصفهم بقوله: ولا تطع من أغفلنا قلبه»; «أغفلت الكتاب: إذا جعلته خاليا من الكتابة»)', note_en = 'Faith written in hearts (58:22) ↔ a heart left blank (18:28). al-Rāghib sets the two verses against each other.' WHERE id = 'DID:كتب:اغفل' AND status = 'live';
UPDATE ar_ling_root_didd SET note_en = 'For نُزُول, stopping at a place — not تَنزِيل, sending down. Settling in ↔ setting off. Not صَعِدَ — no book pairs it with نزل.' WHERE id = 'DID:نزل:رحل' AND status = 'live';
